#!/usr/bin/env bash
# Builds server/coin_shop.txt from costumes.tsv (the costume list) and the gear list below.
set -euo pipefail
cd "$(dirname "$0")"
COIN=2600000
costumes=$(grep -v '^#' costumes.tsv | awk -F'\t' 'NF>=2{printf ",%s:%s",$1,$2}')
gear=",2600001:400,2600002:400,2600003:400,2600004:400,2600005:300"
{
cat <<'HDR'
//===== HuffLabs RO =========================================
//= HuffLabs Coin merchants (Prontera). Generated by build-shop.sh, don't edit by hand.
//= Costumes: costumes.tsv. Pay with HuffLabs Coins (item 2600000).
//==========================================================

HDR
printf 'prontera,146,188,5\titemshop\tCostume Merchant#hlro\t4_F_KAFRA9,%s%s\n' "$COIN" "$costumes"
printf 'prontera,166,188,3\titemshop\tGear Merchant#hlro\t4_M_REPAIR,%s%s\n' "$COIN" "$gear"
} > server/coin_shop.txt
echo "wrote server/coin_shop.txt ($(grep -vc '^#' costumes.tsv) costumes)"
